{"name":"create_tic_tac_toe_game","type":"sequential","steps":[
  {"tool":"shell_exec","args":{"command":"mkdir -p "$profile.workspace/tictactoe""},"description":"Create a new folder for the Tic Tac Toe game in the user's workspace"},
  {"tool":"file_write","args":{"path":"$profile.workspace/tictactoe/index.html","content":"<!DOCTYPE html>
<html>
<head>
<meta charset='UTF-8'>
<meta name='viewport' content='width=device-width, initial-scale=1.0'>
<title>Tic Tac Toe</title>
<style>
body { font-family: Arial, sans-serif; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; margin: 0; }
#board { display: grid; grid-template-columns: repeat(3, 100px); grid-gap: 5px; }
.cell { width: 100px; height: 100px; display: flex; align-items: center; justify-content: center; font-size: 2em; background-color: #f2f2f2; cursor: pointer; }
.cell:hover { background-color: #ddd; }
#message { margin-top: 20px; font-size: 1.2em; }
button { margin-top: 10px; padding: 8px 12px; font-size: 1em; }
</style>
</head>
<body>
<h1>Tic Tac Toe</h1>
<div id='board'></div>
<div id='message'></div>
<button onclick='resetGame()'>Reset</button>
<script>
const boardElement = document.getElementById('board');
const messageElement = document.getElementById('message');
let board = Array(9).fill(null);
let currentPlayer = 'X';
let gameActive = true;
function createBoard() {
  boardElement.innerHTML = '';
  board.forEach((cell, index) => {
    const cellElement = document.createElement('div');
    cellElement.classList.add('cell');
    cellElement.textContent = cell;
    cellElement.addEventListener('click', () => handleCellClick(index));
    boardElement.appendChild(cellElement);
  });
}
function handleCellClick(index) {
  if (!gameActive || board[index]) return;
  board[index] = currentPlayer;
  createBoard();
  if (checkWinner()) {
    messageElement.textContent = `Player ${currentPlayer} wins!`;
    gameActive = false;
  } else if (board.every(cell => cell)) {
    messageElement.textContent = 'Draw!';
    gameActive = false;
  } else {
    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    messageElement.textContent = `Player ${currentPlayer}'s turn`;
  }
}
function checkWinner() {
  const winPatterns = [
    [0,1,2],[3,4,5],[6,7,8],
    [0,3,6],[1,4,7],[2,5,8],
    [0,4,8],[2,4,6]
  ];
  return winPatterns.some(pattern => {
    const [a,b,c] = pattern;
    return board[a] && board[a] === board[b] && board[a] === board[c];
  });
}
function resetGame() {
  board = Array(9).fill(null);
  currentPlayer = 'X';
  gameActive = true;
  messageElement.textContent = `Player ${currentPlayer}'s turn`;
  createBoard();
}
createBoard();
messageElement.textContent = `Player ${currentPlayer}'s turn`;
</script>
</body>
</html>"},"description":"Create the HTML, CSS, and JavaScript code for the Tic Tac Toe game"},
  {"tool":"app_open","args":{"target":"$profile.workspace/tictactoe/index.html"},"description":"Open the newly created Tic Tac Toe game in the default web browser"}
]}

